mapper.select:
select b.id,b.book_name,b.author,b.price,b.stock,b.category_id,c.category_name
from book b left join category c on b.category_id = c.id
where b.id=#{id}

select b.id,b.book_name,b.author,b.price,b.stock,b.category_id,c.category_name
from book b left join category c on b.category_id = c.id
where b.category_id=#{categoryId}
